-- skill_game · off_tee
($drill$Out of Bounds Driver Game$drill$,
 $drill$Hit 5 straights, 5 draws, 5 fades to a 20-yard fairway with +5 / 0 / −5 scoring for fairway / safe miss / OB — your total tells you which shape to play on the course.$drill$,
 25, 'off_tee', '{range,sim}', '{developing,competitive}',
 $drill$**Why it works.** Alistair Davies (Golf Monthly Top 25 Coach) reframes range driver practice from "hit balls and watch shape" to "score each shape against a real consequence." Imagine a 20-yard-wide fairway, OB on either side. Hit five straights, five draws, five fades. Each ball that finds the fairway earns +5; a ball on the "safe" side (off the fairway but not OB) is 0; a ball OB is −5. The penalty changes the math you do on the tee: a shape that lands 4 of 5 fairways but 1 OB scores +15 (4×5 − 5), whereas a shape that lands 3 of 5 fairways with 2 safe misses scores +15 too — and one of them is far safer at a tournament. Per-shape totals tell you which shape your swing actually owns under pressure (consistent positive) versus which one is the lottery ticket (high mean, big variance). "The shot shape that gives you the highest score is the one you should then look to play when you face a similar scenario on the course." **Who it helps most.** Developing and competitive players who already shape the ball on demand and need to pick the shape they actually play on a real tee. Not for beginners — needs three working shapes and a usable corridor. **Setup.** A driving range with visible distance markers; pick two landmarks (sticks, flags, trees) to define a 20-yard corridor at driver-carry distance. Driver, 15 balls. Scorecard or notes app. **How.** From the same tee, hit 5 straight, 5 draw, 5 fade — full routine on each, no do-overs. Score each ball +5 fairway / 0 safe side / −5 OB. Tally three per-shape totals (each −25 to +25) and an overall (−75 to +75). **Time & frequency.** 20–25 minutes weekly during a tee-shot block; the per-shape pattern is the data, the overall is the score-to-beat. **Success metric, by level.** • Developing: positive total; one shape clearly highest. • Competitive: overall ≥ +25; the highest shape repeats session to session. **Common mistakes.** Skipping the routine; "trying harder" on the OB side to recover (drop the shape, don't push it); 30-yard corridor (no useful signal — a real fairway is ~30 m); calling close misses "safe" when they're actually OB by your landmarks (be honest).$drill$,
 '{break_80,break_70s,scratch}', '{dispersion,start_line,trajectory}', 'skill_game',
 $drill$Alistair Davies, Golf Monthly Top 25 Coach$drill$, 'https://www.golfmonthly.com/tips/driving-range-games-168172', 'oga', true),

-- skill_game · approach
($drill$Flagstick Challenge$drill$,
 $drill$Pick one approach distance between 60 and 130 yards, hit 20 balls, and count how many finish within a flagstick of the target — a single repeatable number that's brutal to fake.$drill$,
 20, 'approach', '{range,sim}', '{casual,developing,competitive}',
 $drill$**Why it works.** Will Shaw (PhD, MSc, PGA Pro — Golf Insider UK) built the Flagstick Challenge to fix the highest-leverage scoring distance — 60 to 130 yards, where amateurs lose the most strokes per round versus Tour. Pick one target in that band, define the success zone as "within a flagstick length of the target" (roughly 8 feet), and hit 20 balls with a full routine. One point per ball inside the zone, zero outside. The maximum is 20; your number is what you record and try to beat next session. The single-distance focus is deliberate — it's a clean signal on dispersion at that distance, not a smeared average across your whole bag. As you grow, narrow the distance ladder by 10 yards or tighten the zone to a putter length. **Who it helps most.** Casual players who never measure wedge/short-iron accuracy and don't know their dispersion at 80 yards; developing players plateaued on GIR; competitive players auditing scoring-zone consistency. **Setup.** A range with visible distance markers or a launch monitor; wedges/short irons covering 60–130 yards; 20 balls; scorecard. Pick ONE target distance and commit to it for the session. **How.** Imagine an 8-foot circle around the target (a flagstick length). Run your full routine on every ball, then score: 1 if it finishes inside the circle, 0 outside. Note where misses tend to finish (short, long, left, right) — pattern data, not just the count. Tally /20; record the score AND the distance you chose. To progress, narrow the success zone to a putter length, or shorten the target distance band. **Time & frequency.** 20 minutes weekly during a scoring-zone block; rotate distances across sessions. **Success metric, by level.** • Casual: 6 of 20 at 90 yds. • Developing: 10 of 20 at 100 yds; consistent miss direction. • Competitive: 14 of 20 at 120 yds; misses tight around the zone. **Common mistakes.** Rotating distances within a single 20-ball set (smears the data); skipping the routine; calling close-but-out misses "in" (be honest); never recording the score (no benchmark to beat).$drill$,
 '{break_90,break_80,break_70s,scratch}', '{dispersion,distance_control}', 'skill_game',
 $drill$Will Shaw, PhD, MSc, PGA Pro (Golf Insider UK)$drill$, 'https://golfinsideruk.com/golf-practice-games-long-game/', 'oga', true),

($drill$Iron Scoring Game$drill$,
 $drill$Hit 20 balls each to three self-chosen distances — 3 points inside a flagstick, 1 point inside three flagsticks, 0 outside — for a 180-point dispersion benchmark across your scoring zones.$drill$,
 30, 'approach', '{range,sim}', '{developing,competitive}',
 $drill$**Why it works.** Will Shaw's Iron Scoring Game expands the Flagstick Challenge into a three-distance dispersion benchmark. Pick three distances you'll face on the course (e.g., 90, 130, 170 yards); hit 20 balls to each. Inner zone — inside a flagstick length (~8 ft) — scores 3 points. Outer zone — between one and three flagsticks (8 to 21 ft) — scores 1 point. Outside both zones is 0. Maximum score is 180 (60 × 3); a Tour player would push above 120; a developing player getting to 60 is real progress. The tiered scoring is what makes it a scoring game rather than a hit-or-miss test: you can lose ground by drifting fat misses outside both zones AND gain ground by tightening your distribution toward dead-center. Shaw explicitly tells you to note shot finishes and miss directions — the pattern is half the value. **Who it helps most.** Developing and competitive players who own iron contact and want a real benchmark across the whole scoring zone, not just one distance. Best with a launch monitor or sim; visible range markers work if calibrated. **Setup.** Pick three target distances spanning your scoring zone (short / mid / long). Mark or visualize an 8-ft inner circle and a 21-ft outer circle at each. Three irons or wedges to match. 60 balls. Scorecard with three columns. **How.** Hit 20 balls per distance in blocks (not rotating ball-to-ball — this drill is a dispersion test, not a randomization test; randomization lives in `random` mode). Score 3 / 1 / 0. After 60 balls total your three columns and combined. Note WHERE misses tend to finish — short, long, left, right — that's the actionable read. **Time & frequency.** 30 minutes weekly to monthly as a calibration benchmark; not a daily drill. **Success metric, by level.** • Developing: 60+ of 180; pattern identifies one distance to focus on. • Competitive: 100+ of 180; miss direction tight, not scattered. **Common mistakes.** Rotating clubs ball-to-ball (different drill); inventing distances on the fly (commit and write them down); only counting inner-zone hits (the 1-point band is the dispersion data); changing distances between sessions so you can't compare scores.$drill$,
 '{break_80,break_70s,scratch}', '{dispersion,distance_control,start_line}', 'skill_game',
 $drill$Will Shaw, PhD, MSc, PGA Pro (Golf Insider UK)$drill$, 'https://golfinsideruk.com/golf-insider-practice-system/', 'oga', true),

-- skill_game · around_green
($drill$Chipping Zone Challenge$drill$,
 $drill$Hit 10 chips from 10, 15, or 20 yards into three concentric rings around the hole — 2 points inside the closest, 1 in the next, 0 outside — and chase the 20-point target.$drill$,
 20, 'around_green', '{short_game}', '{casual,developing,competitive}',
 $drill$**Why it works.** Will Shaw (PhD, MSc, PGA Pro — Golf Insider UK) builds his chipping benchmark around three concentric rings the radius of a standard 9-iron. Pick a chip distance (10, 15, or 20 yards); hit 10 balls. The article specifies a 20-point target out of 10 shots — the OGA convention to hit that ceiling is 2 points for balls inside the closest ring, 1 for the next, 0 outside. The ring layout matters more than the exact point math: at 9-iron-length radius (~3 ft inner, ~6 ft middle), the target zones are tight enough to expose dispersion that "near the hole" hides. Shaw's coaching prompt is explicit: track WHERE misses finish — short, long, left, right — because the pattern tells you whether the issue is club selection (distance bias) or strike (lateral bias). The 20-point ceiling makes 14 a strong developing benchmark and 16+ a sign you've earned a step up to 15 or 20 yards. **Who it helps most.** Every level. The 10-yard variant is excellent for casual players grooving basic chip mechanics; 15 and 20 are the developing/competitive proving grounds. **Setup.** Practice short-game green; one chip distance you'll commit to for all 10 balls; a 9-iron laid horizontally to lay out three concentric rings around the hole (inner ~3 ft, middle ~6 ft, outer ~9 ft). 10 balls, your favorite chipping wedge. Scorecard. **How.** Hit 10 chips from your chosen distance. Score each: 2 inside the inner ring, 1 in the middle, 0 outside. Tally /20 and note miss pattern. Beat your score next session; move up to the next distance when you regularly hit 16+. *(Per-zone values inferred from the article's "20-point target from 10 shots" — Shaw doesn't spell point values explicitly.)* **Time & frequency.** 20 minutes weekly. **Success metric, by level.** • Casual: 8 of 20 at 10 yds. • Developing: 14 of 20 at 15 yds; misses concentrated, not scattered. • Competitive: 16+ at 20 yds. **Common mistakes.** Rotating distances mid-set (10 balls at one distance is the drill); calling the middle ring "close enough" without scoring it 1 (you'll miss the dispersion signal); not noting miss direction; setting rings tighter than 9-iron radius (defeats the calibration to Shaw's benchmark).$drill$,
 '{break_100,break_90,break_80,break_70s}', '{chip_contact,distance_control}', 'skill_game',
 $drill$Will Shaw, PhD, MSc, PGA Pro (Golf Insider UK)$drill$, 'https://golfinsideruk.com/golf-chipping-practice-lower-your-scores/', 'oga', true),

($drill$Tailor's Pitching Challenge$drill$,
 $drill$Hit 5 pitches from 15–20 yards and sum the total feet to the pin — Will Shaw's challenge is to get the cumulative under 30 feet, an average inside 6 feet per shot.$drill$,
 15, 'around_green', '{short_game}', '{casual,developing,competitive}',
 $drill$**Why it works.** Will Shaw's Tailor's Pitching Challenge swaps point-based scoring for the rawer measurement that actually predicts up-and-down conversion: distance from the hole. Pick a pin 15 to 20 yards away; hit 5 pitch shots; walk up and measure (or pace) each ball's distance to the pin in feet; sum the five distances. Shaw's pass mark is **under 30 feet total** — meaning an average of 6 feet or closer — which is roughly Tour-level proximity from that distance. A 50-foot total tells you your average pitch leaves a 10-footer; a 100-foot total flags a strike or distance problem you can't see from "they kind of go that way." The total-feet metric also resists the rounding-up bias that comes with binary in/out scoring — every foot you tighten dispersion shows up directly. **Who it helps most.** Casual players who can already make solid contact and need to learn that "around the hole" varies wildly when measured; developing/competitive players auditing scoring proximity. **Setup.** Short-game green with a flag; 15–20 yards of room; pitch wedge or 56°; 5 balls; a yardage measurer or rangefinder (or just pace). **How.** Hit 5 pitches from one consistent spot (don't drop a closer ball if one comes up short). Walk to each, measure feet to the pin, write it down. Sum the five; the total is your score. Beat the total next session. Tour-level reference: under 30 ft total. Note where misses miss — short, long, left, right. **Time & frequency.** 15 minutes weekly during a wedge block. **Success metric, by level.** • Casual: under 60 ft total. • Developing: under 40 ft. • Competitive: under 30 ft (Shaw's pass mark). **Common mistakes.** Walking to the closest ball first and being "encouraged" — measure them all honestly; rounding down; rotating distances within the 5-ball set; hitting until you get a good one (the 5 you hit is the score).$drill$,
 '{break_100,break_90,break_80,break_70s}', '{distance_control,chip_contact}', 'skill_game',
 $drill$Will Shaw, PhD, MSc, PGA Pro (Golf Insider UK)$drill$, 'https://golfinsideruk.com/golf-chipping-practice-lower-your-scores/', 'oga', true),

($drill$15 Chips Game$drill$,
 $drill$Hit 5 easy, 5 medium, and 5 hard chips around the green — 1 point per ball within two club-lengths of the hole, bonus for a chip-in — and chase a higher score next session.$drill$,
 20, 'around_green', '{short_game}', '{casual,developing,competitive}',
 $drill$**Why it works.** Luke Benoit (Director of Instruction at Interlachen Country Club in Edina, Minnesota), writing in Golf Digest's "15 Best Practice Games" feature, structures his short-game scoring game around three levels of difficulty rather than three distances. Pick a routine easy chip from the fringe; pick a medium-difficulty chip from light rough or a slightly awkward lie; pick a hard chip — short-sided, bad lie, or downhill. Hit 5 from each (15 total). For every ball that finishes within **two club-lengths** of the hole, you earn 1 point; a holed chip earns a bonus point (OGA convention: +1 extra for a chip-in, per the article's "made chips receive bonus points" rule). The 2-club-length zone is wider than Tour proximity scoring — Benoit's framing is "anywhere you'd be confident with the next putt" — and the gradient of difficulty across the three rounds maps to what you actually face on the course. Max score is 15 (+ chip-in bonuses); track it across sessions and chase the trend, not any one number. **Who it helps most.** Casual and developing players who want to expose which difficulties they own and which they avoid. Competitive players use it as variety calibration. **Setup.** Short-game green with multiple lies and pin angles; pick 3 spots in advance — easy, medium, hard — and write them down so you can replay the same test next session. Chipping wedge, putter, 15 balls. Scorecard. **How.** Round 1: 5 chips from the easy spot; score each (+1 within 2 club-lengths, +1 extra chip-in). Round 2: medium. Round 3: hard. Sum to /15-plus-bonuses. Replay the same three spots next session and chase a higher total. **Time & frequency.** 20 minutes weekly. **Success metric, by level.** • Casual: 6+ of 15. • Developing: 10+ of 15; the hard round above 3. • Competitive: 12+; the hard round 4+. **Common mistakes.** Picking three similar-difficulty spots; switching the spots session to session (kills comparison); only counting holed chips (the 2-club-length zone is the metric); skipping the hard round.$drill$,
 '{break_100,break_90,break_80}', '{chip_contact,distance_control}', 'skill_game',
 $drill$Luke Benoit, Director of Instruction at Interlachen CC (Golf Digest / Australian Golf Digest)$drill$, 'https://www.australiangolfdigest.com.au/the-15-best-golf-practice-games/', 'oga', true),

($drill$6-Foot Circle Chip Score$drill$,
 $drill$Hit 50 chips from 15 yards — +2 for each ball inside a 6-foot circle, −1 outside, then putt every ball with +3 for makes and −1 for misses — and chase the 250-point ceiling.$drill$,
 25, 'around_green', '{short_game,putting}', '{casual,developing,competitive}',
 $drill$**Why it works.** Nick Foy's chipping scoring game stacks two metrics into one number: chip proximity AND putt conversion. From 15 yards off the green, hit 50 chips (five sets of 10). Each chip that finishes inside a 6-foot circle around the hole scores +2; each chip outside scores −1. Then putt every ball: a holed putt is +3, a missed putt is −1. The maximum is 250 (50 × 2 chip + 50 × 3 putt = 250); Foy calls **above 200 "professional level."** The combined chip-and-putt scoring fixes the single biggest hole in chipping practice — players who chip well to a 6-foot zone but can't roll the next putt in are not actually saving strokes on the course. The penalty for missed putts also keeps you honest under the chip-to-3-feet shortcut: a chip that lands closer makes the putt easier and produces a higher combined score. **Who it helps most.** Every level. Casual players use the chip score in isolation; developing/competitive players run the full chip-plus-putt for the real up-and-down benchmark. **Setup.** Short-game green with a flag and rollable surface; 15-yard chip distance from one consistent spot; tape, tees, or a measuring string to mark a 6-ft circle around the hole; chipping wedge and putter; 50 balls (chip + retrieve in batches of 10 if you don't have 50). Scorecard. **How.** Set 1: hit 10 chips from 15 yds, score each chip (+2 inside circle / −1 outside), then putt each ball (+3 made / −1 missed). Repeat 4 more sets of 10. Sum to /250. **Time & frequency.** 25 minutes weekly during a short-game block. **Success metric, by level.** • Casual: 100+ of 250. • Developing: 150+. • Competitive: 200+ (Foy's pro-level threshold). **Common mistakes.** Skipping the putt (halves the data); resetting the circle bigger because chips don't land in it (the circle is the standard); not tracking the chip and putt scores separately (the diagnostic value is in seeing which side leaks); only running one or two sets instead of all five (50 is the benchmark sample size).$drill$,
 '{break_100,break_90,break_80}', '{chip_contact,distance_control,lag}', 'skill_game',
 $drill$Nick Foy (Foy Golf Academy)$drill$, 'https://nickfoygolf.com/chipping-practice-routine-5-golf-drills/', 'oga', true),

($drill$US National Junior Team Bunker Test$drill$,
 $drill$Hit 15 bunker shots, measure each in inches to the pin (200-inch cap for misses), throw out the highest 3, sum the remaining 12 — lower is better, beat your number.$drill$,
 25, 'around_green', '{short_game}', '{developing,competitive}',
 $drill$**Why it works.** The U.S. National Junior Team's bunker proximity test (head coach Chris Zambri; assistant coach Tiffany Joh, who runs the pin position from inside the green) measures what actually matters in bunker play: how close, on average, you finish — not whether you make the once-a-month hole-out. Hit 15 bunker shots from one consistent lie. After each, measure (or pace) the distance to the pin in inches; cap any genuine miss at 200 inches. Throw out the worst three numbers (the outliers — a chunk, a thin, a flyer). Sum the remaining 12. That total is your score; the lower it is, the better your bunker play, and you chase a lower total next session. The drop-the-worst-3 rule keeps a single bad swing from torching the diagnostic — Tour players have bad bunker shots too. The 200-inch (~17-foot) cap normalizes truly bad misses so they don't dominate the sum at the expense of the 14 close shots. The result is a stable, replayable number that's sensitive to real improvement and not to one outlier. **Who it helps most.** Developing and competitive players auditing bunker proximity; juniors and amateurs who want a real Tour-format benchmark. Not for true beginners — needs reliable contact. **Setup.** A practice bunker; one consistent lie; a rangefinder or a yardage measure (paces converted to inches works); 15 balls. Scorecard with 15 cells. **How.** Hit 15 bunker shots from the same spot to the same flag. After each ball, measure feet-to-pin and convert to inches (or cap at 200 inches if the shot finishes longer than 17 ft / barely on the green / off the green). Write down all 15 numbers. Cross out the three highest. Sum the remaining 12 — that's your score. Beat the total next session. **Time & frequency.** 25 minutes weekly during a bunker block; one of the few drills that gets sharper as conditions vary. **Success metric, by level.** • Developing: under 1,500 inches (avg ~125"/10.4 ft per scoring ball). • Competitive: under 1,000 inches (avg ~80"/6.7 ft). • Tour reference: U.S. Junior Team members regularly post sub-700. **Common mistakes.** Eyeballing instead of measuring; measuring only the close ones; forgetting to cap the genuine misses (one chunk dominates the sum); throwing out fewer than 3 (or more) — the rule is exactly 3; rotating lies within a set (the drill needs one lie per session to be comparable).$drill$,
 '{break_90,break_80,break_70s,scratch}', '{bunker,distance_control}', 'skill_game',
 $drill$Chris Zambri (head coach), Tiffany Joh (assistant) — U.S. National Junior Team (Golf.com)$drill$, 'https://golf.com/instruction/how-practice-like-us-national-junior-team/', 'oga', true),

-- skill_game · putting
($drill$Lag-It Points Game$drill$,
 $drill$Lay a club 18–24 inches past the hole and putt from any lag distance — 2 points for a make, 1 for a putt past the hole but short of the club, 0 for short or hitting the club.$drill$,
 20, 'putting', '{putting}', '{casual,developing,competitive}',
 $drill$**Why it works.** Andy Hilts (VP of Instruction & Education at GolfTEC) built Lag-It around a single insight: amateur three-putts almost always come from being short, not long. The fix is a physical target that rewards rolling the ball past the hole but inside a controlled zone. Place a golf club on the green 18 to 24 inches past the hole. Now lag from any distance you want to train — 30, 40, 50 feet. Score every putt: a made putt is 2 points; a putt that finishes past the hole but doesn't reach (or hit) the club is 1 point; a putt left short of the hole is 0; a putt that hits the club or rolls past it is 0. The point values bias your speed control upward — the optimal lag finishes 6 to 24 inches past the hole, exactly the range Pelz's data identifies as the highest-conversion zone — and the +1 zone is wide enough that you can train at multiple distances in one session. Total your points across however many lag distances you choose; that total is your score-to-beat. **Who it helps most.** Every level — three-putt avoidance is the single biggest scoring leak for casual and developing players. Competitive players run it as pre-round speed calibration. **Setup.** A practice green with a hole; a golf club; balls (10 per distance is a reasonable sample); a scorecard. Pick 3–4 lag distances (e.g., 30, 40, 50 ft) — write them down. **How.** Lay the club 18–24" past the hole, perpendicular to your line. Putt the first distance (10 balls, score each), then move to the next distance, and so on. Sum points across all stations. Beat your total next session. The bias toward +1 (past but not past the club) trains you to never leave a lag short. **Time & frequency.** 20 minutes 2×/week during a lag block; 10 minutes pre-round as speed calibration. **Success metric, by level.** • Casual: positive total, with no zeros from being short. • Developing: 2+ makes per distance, most others scoring 1. • Competitive: 3+ makes from 30 ft; almost no short leaves. **Common mistakes.** Putting from one distance only (defeats the lag calibration); moving the club closer (raises the make rate but loses the "no-short" training); not tracking which distance produced the short putts (the actionable pattern); jogging the ball to the hole at the end (leave it to read the result).$drill$,
 '{break_100,break_90,break_80,break_70s}', '{lag,distance_control}', 'skill_game',
 $drill$Andy Hilts, VP Instruction & Education at GolfTEC$drill$, 'https://scramble.golftec.com/blog/2014/11/lag-putting-game/', 'oga', true),

($drill$Hole 100 Feet of Putts$drill$,
 $drill$Hit one 5, 10, 15, and 20-foot putt to each of 5 different hole locations — 20 putts, 250 feet possible — and add up the total footage of putts holed. Tour level is 100 feet.$drill$,
 25, 'putting', '{putting}', '{developing,competitive}',
 $drill$**Why it works.** Phil Kenyon (putting coach to multiple major winners; quoted in Today's Golfer) scores his pressure-free putting test by aggregate footage of holed putts, not make count. Pick a hole on the practice green; hit one putt each at 5, 10, 15, and 20 feet using your full pre-shot routine. Now move to a different hole location with a different angle of break, and repeat the four putts. Repeat across 5 hole locations total — 20 putts, 250 feet of possible footage. After each holed putt, tally the distance: a 20-footer that drops is +20 feet, a 5-footer that drops is +5 feet. Misses count 0 regardless of how close. Sum the holed footage. Kenyon's PGA Tour winner benchmark is **100 feet of holed putts out of 250 possible**; the all-time best he's recorded is Henrik Stenson at 145. The footage-weighting matters: a player making lots of 5-footers but no long ones scores low; a player who mixes in a 20-footer climbs fast. The 5-hole rotation eliminates "I just keep making this one putt" — you read 5 different breaks, 5 different angles, on every distance. **Who it helps most.** Developing and competitive players who already convert short putts and need to test the full distance band. Not for casual players — the long putts will dominate the score uselessly without baseline lag skill. **Setup.** Practice green with multiple hole locations and break variety; 4 balls; tees or markers at 5/10/15/20 ft from each hole; scorecard. **How.** From Hole 1: hit your 5-footer (routine), then 10, 15, 20 ft. Record whether each dropped and the holed footage. Move to Hole 2 (different angle/break), repeat. Total 5 holes × 4 putts = 20 putts. Sum holed footage. Beat next session; chase the 100-ft Tour benchmark. **Time & frequency.** 25 minutes weekly. **Success metric, by level.** • Developing: 40+ ft holed. • Competitive: 70+ ft. • Tour reference: 100 ft = Tour winner level (Kenyon's bar). **Common mistakes.** Same hole all 20 putts (loses the read variety); skipping the routine; counting "close" misses; chasing the 20-footers and skimping on the 5s (the math doesn't work — every 5-footer made = the 5-footer; every 5-footer missed = 0).$drill$,
 '{break_90,break_80,break_70s,scratch}', '{short_putts,lag,distance_control,green_reading}', 'skill_game',
 $drill$Phil Kenyon, putting coach (Today's Golfer)$drill$, 'https://www.todays-golfer.com/features/instruction-features/2020/september/phil-kenyon-golf-putting-tips/', 'oga', true),

($drill$Putting Skill Test (18-Putt)$drill$,
 $drill$Three putts each from six distance bands (3–5 / 5–10 / 10–15 / 15–20 / 20–25 / 25–30 ft) = 18 birdie putts. Made = 1 stroke, missed = 2 (tap-in). Total vs par 72.$drill$,
 30, 'putting', '{putting}', '{developing,competitive}',
 $drill$**Why it works.** Bradley Turner (PGA Certified Professional; Executive Director, Keiser University College of Golf) frames an 18-putt test as if you've hit every green in regulation — 18 birdie putts spread across the six distance bands you actually face. Hit 3 putts each from 3–5, 5–10, 10–15, 15–20, 20–25, and 25–30 feet (18 total). Each made putt is a birdie (1 stroke); each missed putt is treated as a tap-in two-putt (2 strokes). Sum to your simulated 18-hole putting round; subtract from par 72 for an under-par score. The PGA Tour average works out to **roughly 66.1** based on Tour conversion percentages and the typical 0.50 three-putts per round — meaning a Tour player rolling this test would shoot about 6 under. Scratch amateurs land near 67–68; mid-handicaps closer to 70–71. The structure is what makes it a real benchmark: it samples the full putting distance spectrum a round actually demands, in proportion, and the par-72 scoring is intuitive and comparable across sessions. **Who it helps most.** Developing and competitive players auditing total putting strokes versus Tour benchmarks; players prepping for a Pelz-style structured test without the 80-shot scale. **Setup.** Practice green with multiple hole locations and variable break; tees or markers at 3 putts per band × 6 bands = 18 stations; scorecard. (Spread stations across the green so you don't rep the same break repeatedly.) **How.** From each band, hit 3 putts to 3 different hole locations within that distance window. Record each: made = 1, missed = 2 (no third putt — assume tap-in). Sum to your 18-hole total; subtract from par 72 for your under-par score. **Time & frequency.** 30 minutes monthly as a benchmark — not weekly; the variance per session is high and you want session-to-session signal. **Success metric, by level.** • Developing: par or 1–2 under. • Competitive: 3–5 under (68–69 raw). • Tour benchmark: 6 under (66.1, Turner's published Tour avg). **Common mistakes.** Putting 18 putts to the same hole (no read variety); skipping the missed-putt = 2 scoring (under-counts strokes); running it weekly (high variance, low signal); counting close misses (the rule is hard make or miss).$drill$,
 '{break_80,break_70s,scratch}', '{short_putts,lag,distance_control}', 'skill_game',
 $drill$Bradley Turner, PGA Certified Professional, Executive Director — Keiser University College of Golf$drill$, 'https://collegeofgolf.keiseruniversity.edu/test-your-putting-skill/', 'oga', true),

($drill$Makes Drill$drill$,
 $drill$Five balls each at 3, 4, 11, and 12 feet around the same hole — 20 putts total, simply count makes. PGA Tour pro Sam Ryder's go-to short-putt scoring game.$drill$,
 20, 'putting', '{putting}', '{developing,competitive}',
 $drill$**Why it works.** Sam Ryder (PGA Tour player; coached interview in Golf.com by Brendon R. Elliott, PGA) keeps his scoring game radically simple — count makes — because the simplicity is what makes it replayable enough to compete against. Place 5 balls at 3 feet from the hole (around the circle, so each is a different break); putt them all. Move to 4 feet; putt all 5. Then 11 feet; then 12 feet. 20 putts total. Total makes is your score; "keep track of how many putts you make, and you can compete against yourself or friends to get the highest score possible." The 3 and 4-foot work locks in the must-make putts; the 11 and 12-foot work attacks the band where amateurs lose the most strokes per round (the make rate falls off a cliff from 6 to 12 feet). The combination makes it both a confidence drill and a real diagnostic — a player making 10 of 10 inside 4 ft but only 1 of 10 outside 10 ft is doing one job and not the other. Ryder runs this regularly during Tour weeks; the simplicity is the feature. **Who it helps most.** Developing and competitive players. Casual players will get crushed by the 11–12 ft band; better to drill 3–4 ft alone first. **Setup.** Practice green with a hole; tees or markers at 3, 4, 11, 12 ft (5 markers per distance around the hole — vary the break direction at each); 5 balls per distance; scorecard. **How.** Start at 3 ft: hit all 5 putts, count makes. Move to 4 ft: 5 putts, count makes. 11 ft: 5 putts. 12 ft: 5 putts. Total /20. Beat your score next session. To add a focused short-band variant, run only 3 and 4 ft (10 putts, /10). **Time & frequency.** 15–20 minutes 2–3×/week — quick enough to slot into any session. **Success metric, by level.** • Developing: 10+ of 20 (inside 4 ft near-perfect; ~1–2 makes outside 10 ft). • Competitive: 14+ of 20; inside 4 ft = perfect; 3–4 makes outside 10 ft. • Tour reference: Tour avg from 11–12 ft is ~25–30%, so ~3 of 10 outside is solid. **Common mistakes.** Putting all 5 from the same line (loses the break variety the circle gives); not running the long band (the 11–12 ft work is the leverage); skipping the short band when bored (the 3-footers ARE the score, on a course); not recording the score (no benchmark to chase).$drill$,
 '{break_90,break_80,break_70s,scratch}', '{short_putts,distance_control}', 'skill_game',
 $drill$Sam Ryder (PGA Tour) via Brendon R. Elliott, PGA — Golf.com$drill$, 'https://golf.com/instruction/putting/sam-ryder-putting-drills-play-smart/', 'oga', true),

($drill$Drawback Drill$drill$,
 $drill$Play 9 simulated holes — first putt 25–40 ft, drawback rule pushes any missed putt back a putter-length until you hole it. Total strokes across all 9 is your score; beat it.$drill$,
 25, 'putting', '{putting}', '{developing,competitive}',
 $drill$**Why it works.** Trent Wearner (GOLF Top 100 Teacher) layers a punishing mechanic on a 9-hole simulated putting round: every missed putt gets drawn back ONE putter-length further from the hole before your next attempt. A lag from 35 feet that finishes 2 feet short normally becomes a 5-foot follow-up (3 feet plus a putter length). Miss the 5-footer? Now you're at 8 feet. The drawback rule attacks the most expensive amateur putting fault — the speed-control miss that leaves an awkward second putt — by literally making it cost more. Pick 9 holes on the practice green; first putt of each must be 25 to 40 feet (vary it). Play each hole until holed, drawing back on every miss. Score each hole by total strokes (2 = lag-and-make; 3 = lag, miss, drawback-make; 4 = lag, miss-short, drawback-miss, drawback-make; etc.). Sum all 9 — the OGA convention is "beat your lowest 9-hole drawback total next session" since the source doesn't publish a target. The brutal feedback is that loose lag putting compounds: leaving a 30-footer 4 feet short and missing the 4-footer turns a 2 into a 4 fast. **Who it helps most.** Developing and competitive players who can already roll a lag inside 5 feet; the drawback rule punishes anyone who can't. Not for casual — the drawback will spiral and discourage. **Setup.** Practice green with multiple hole locations; 9 starting spots picked in advance, each 25–40 ft from the chosen hole (write them down so you can replay the same 9 next session); one putter length as the drawback unit; a ball; scorecard. **How.** From spot 1: lag putt, miss → draw the ball back one putter-length on the same line, try again, repeat until holed. Score = total strokes. Repeat for the other 8 spots. Sum 9 hole scores. Beat your total next session. **Time & frequency.** 25 minutes weekly. **Success metric, by level.** • Developing: total 27 or fewer (avg 3 per hole). • Competitive: total 22 or fewer (avg 2.4). • Strong: 18–20 (almost all 2s, one or two 3s). **Common mistakes.** Drawing back on a different line (must be the original line); skipping the drawback when you're tired (defeats the drill); starting closer than 25 ft (loses the lag-feel test); changing the 9 spots every session (no comparison).$drill$,
 '{break_90,break_80,break_70s,scratch}', '{lag,distance_control,short_putts}', 'skill_game',
 $drill$Trent Wearner, GOLF Top 100 Teacher$drill$, 'https://golf.com/instruction/putting/challenging-drill-make-you-better-putter/', 'oga', true);

-- ---------------------------------------------------------------------------
-- Demo courses + holes (par-72 each)
-- ---------------------------------------------------------------------------
do $$
declare
  c1 uuid := gen_random_uuid();
  c2 uuid := gen_random_uuid();
  c3 uuid := gen_random_uuid();
begin
  -- These fixed demo courses are seeded as the table owner with no auth
  -- context; the 0027 rate-limit trigger requires auth.uid()/service_role, so
  -- disable it for the demo inserts and restore it after. Transactional — a
  -- rollback reverts the trigger state too.
  alter table public.courses disable trigger courses_rate_limit_before_insert;

  insert into public.courses (id, name, city, state) values
    (c1, 'Pine Ridge Golf Club', 'Demo', 'USA'),
    (c2, 'Lakeside National', 'Demo', 'USA'),
    (c3, 'Old Mill Links', 'Demo', 'USA');

  insert into public.holes (course_id, number, par, yards, stroke_index)
  select c1, n,
         case when n in (3, 7, 12, 17) then 3
              when n in (5, 14) then 5
              else 4 end,
         case when n in (3, 7, 12, 17) then 165
              when n in (5, 14) then 540
              else 410 end,
         n
  from generate_series(1, 18) as n;

  insert into public.holes (course_id, number, par, yards, stroke_index)
  select c2, n,
         case when n in (4, 8, 11, 16) then 3
              when n in (2, 13) then 5
              else 4 end,
         case when n in (4, 8, 11, 16) then 175
              when n in (2, 13) then 555
              else 425 end,
         n
  from generate_series(1, 18) as n;

  insert into public.holes (course_id, number, par, yards, stroke_index)
  select c3, n,
         case when n in (2, 9, 13, 17) then 3
              when n in (6, 15) then 5
              else 4 end,
         case when n in (2, 9, 13, 17) then 155
              when n in (6, 15) then 525
              else 395 end,
         n
  from generate_series(1, 18) as n;

  alter table public.courses enable trigger courses_rate_limit_before_insert;
end $$;
